# 5 Stateless web tier sessions in DynamoDB - A
Q.append(dict(t="2.1", tp=["Stateless architecture", "Amazon DynamoDB", "Session management", "Elastic Load Balancing"],
p="A company runs a web application on Amazon EC2 instances in an Auto Scaling group behind an Application Load Balancer. User session data is stored in memory on each instance, so the company enabled sticky sessions on the ALB. When the group scales in or an instance fails, users on that instance are logged out, and new instances receive little traffic after scale-out because existing users stay bound to their instances. The company wants instances to be stateless so that any instance can serve any request. Which solution meets these requirements?",
o=["Store session data in an Amazon DynamoDB table keyed by session ID with a TTL attribute for expiration, and disable sticky sessions on the ALB.",
   "Increase the stickiness duration of the ALB cookie to 7 days so that users are rarely moved to a different instance.",
   "Store session data on an Amazon EBS volume attached to each instance and create hourly snapshots of the volumes.",
   "Replace the ALB with a Network Load Balancer and enable source IP affinity so that each client is always routed to the same instance."],
c="A",
w=[("Externalized state", "Keeping sessions in DynamoDB instead of instance memory makes the web tier stateless; any instance can read a user's session."),
   ("Even load and safe scale-in", "Without sticky sessions, the ALB balances requests across all instances, including new ones, and terminating an instance no longer logs users out."),
   ("Automatic cleanup", "DynamoDB TTL deletes expired sessions at no extra cost. (Amazon ElastiCache is an equally common session store.)")],
x={"B": "Longer stickiness makes load imbalance worse and still loses sessions when an instance is terminated.",
   "C": "An EBS volume is attached to one instance, so other instances cannot read the sessions, and snapshots do not help live failover.",
   "D": "Source IP affinity is another form of stickiness; sessions are still lost when an instance fails, and clients behind shared NAT addresses overload single instances."},
e=[("\"Users logged out on scale-in\" / sticky sessions", "Move session state to DynamoDB or ElastiCache to make the tier stateless."),
   ("Stateless vs stateful", "Stateless instances scale horizontally and can be replaced at any time.")]))
# 6 SQS delay queue - C
